{
  "technical_and_design_decisions": [
    "Use Java 17 and Spring Framework 6 (Spring Boot 3) as the baseline runtime and Maven for builds.",
    "For the Receptor client (U1), adapt the referenced receptor-client repository and use Spring WebClient with Jackson JSON for reactive HTTP API calls to Diego runtime.",
    "For stream/job repository refactoring (U2) and persistent stream repository (U4), use Spring Data JPA with a relational database (H2 for tests, PostgreSQL for production) to persist metadata.",
    "For the pluggable runtime SPI (U3), define a RuntimeProvider interface and use Spring's dependency injection with profile/condition-based selection for CF, on-prem, and Mesos implementations.",
    "For Spark/Spark Streaming support (U6), integrate the latest Spark Structured Streaming version compatible with XD and provide sample pipeline DSL definitions.",
    "For Import Options (U8), replace the generic --args passthrough with strongly-typed @ConfigurationProperties bound parameters.",
    "Documentation will be authored in AsciiDoc within the existing project docs module."
  ],
  "assumptions": [
    "The existing Spring XD codebase is available, compiles, and has working test infrastructure; this increment extends it.",
    "The referenced receptor-client GitHub repository provides a sufficient base; we adapt rather than build a client from scratch.",
    "Only three runtime targets (Cloud Foundry, on-prem, Mesos) are required for the SPI; other targets can be added later.",
    "Effort estimates include writing unit and integration tests by the same developer, but exclude separate QA, UAT, deployment, and production support.",
    "The developer is a senior Java/Spring engineer familiar with XD, so no significant training or learning curve is included.",
    "U6 is interpreted as providing XD integration modules and example streaming pipelines for the latest Spark/Spark Streaming specs, not modifying Spark itself.",
    "Documentation tasks (U5, U7) only require writing content in-repo; no separate documentation publishing pipeline work is needed."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Initial design and architecture spike",
      "activity_description": "Analyze existing XD codebase, define interfaces for runtime SPI and repositories, and produce technical design covering U1-U4, U6, and U8.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement Receptor Java client and XD integration (U1)",
      "activity_description": "Adapt the referenced receptor-client, implement API calls to Diego runtime via Receptor, and wire the client into XD runtime.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Refactor stream/job definition repository (U2)",
      "activity_description": "Decouple domain model and repository from module deployment concerns; extract interfaces and move deployment logic elsewhere.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Define pluggable runtime SPI with target implementations (U3)",
      "activity_description": "Define RuntimeProvider SPI, create implementations for Cloud Foundry, on-prem, and Mesos, and integrate selection logic into XD.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Implement persistent repository for streams and failure recovery (U4)",
      "activity_description": "Create persistent store for stream metadata using Spring Data JPA and implement re-establishment of streaming pipes after failure.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Enhance streaming pipeline support for latest Spark/Spark Streaming specs (U6)",
      "activity_description": "Integrate latest Spark Streaming modules, provide sample streaming pipeline definitions, and verify compatibility with latest XD and Spark specs.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Parameterize Import Options and remove --args (U8)",
      "activity_description": "Refactor import option handling to typed, parameterized configuration bound via Spring configuration properties, eliminating the --args passthrough.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Document escape quotes for Sqoop jobs (U5)",
      "activity_description": "Add documentation explaining double escaping \\\\N instead of quoting '\\N' for Sqoop job submission.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Document nesting batch jobs and workflows (U7)",
      "activity_description": "Write user-facing documentation with examples of nesting batch jobs and workflows in XD.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration testing, build, and final verification",
      "activity_description": "Integrate all changes, run full test suite, update CI/build scripts, perform final code review and verification of the increment.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 224
  }
}

